#!/usr/bin/env python3
from pathlib import Path
import base64,zlib,hashlib,sys
EXPECTED="afaca48f14f94087c2fbe8b8a846a7e85ce2b489558223e3b185276106b0d865"
DATA=""""""
raw=zlib.decompress(base64.b64decode(DATA))
if hashlib.sha256(raw).hexdigest()!=EXPECTED: raise SystemExit("BLOCKED patch hash mismatch")
path=Path(sys.argv[1] if len(sys.argv)>1 else "/tmp/v655.patch")
path.write_bytes(raw)
print("PATCH_SHA256="+EXPECTED)
print("PATCH_BYTES="+str(len(raw)))
